mapper.insert:
INSERT INTO rag_recovery_members(generation_id,chunk_id)
SELECT g.generation_id,c.chunk_id FROM rag_recovery_generations g JOIN rag_document_chunks c ON c.document_id=g.document_id
WHERE g.generation_id=#{generationId} AND c.chunk_id=#{chunkId}

mapper.update:
UPDATE rag_recovery_generations SET state=#{state},validation_evidence=#{evidence},validated_at=NOW()
WHERE generation_id=#{expected.id} AND document_id=#{expected.documentId} AND state=#{expected.state}
  AND source_hash=#{expected.sourceHash} AND product_sha=#{expected.productSha}
  AND manifest=#{expected.manifest} AND baseline_hash=#{expected.baselineHash} AND preview_hash=#{expected.previewHash}

UPDATE rag_recovery_generations SET state='INDEX_READY'
WHERE generation_id=#{expected.id} AND document_id=#{expected.documentId} AND state='VALIDATED'
  AND source_hash=#{expected.sourceHash} AND product_sha=#{expected.productSha} AND manifest=#{expected.manifest}
  AND baseline_hash=#{expected.baselineHash} AND preview_hash=#{expected.previewHash}

mapper.insert:
INSERT INTO rag_recovery_baselines(document_id,generation_id)
SELECT document_id,generation_id FROM rag_recovery_generations WHERE generation_id=#{generationId}
  AND document_id=#{documentId} AND state='ACTIVE'
